import { HttpClient, HttpHeaders, HttpParams } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { TostbarService } from '../../../core/services/tost/tostbar.service';
import { caselistRes, tickerList, TicketImageUpload } from '../../interfaces/ticket.interface';

@Injectable({
  providedIn: 'root'
})
export class TicketService {

  constructor(private http: HttpClient, public sStore: SecureStorageService, public tost: TostbarService) { }




  async getTicketList(nCaseid: string): Promise<tickerList[]> {
    const params = new HttpParams().set('nCaseid', nCaseid);
    let res: any = [];
    try {
      res = await firstValueFrom(
        this.http.get<tickerList[]>(
          `${environment.cloudUrl}${environment.coreservice}/ticket/tickets`,
          { params: params }
        )
      );
    } catch (error) {
      console.error(error)
      res = [];
    }
    return res;
  }


  async getAllTicketList(nCaseid: string): Promise<tickerList[]> {
    const params = new HttpParams().set('nCaseid', nCaseid);
    let res: any = [];
    try {
      res = await firstValueFrom(
        this.http.get<tickerList[]>(
          `${environment.cloudUrl}${environment.coreservice}/ticket/casetickets`,
          { params: params }
        )
      );
    } catch (error) {
      console.error(error)
      res = [];
    }
    return res;
  }



  async clearAllResolvedTickets(nCaseid): Promise<boolean> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<any>(`${environment.cloudUrl}${environment.coreservice}/ticket/clearticket`, { nCaseid: nCaseid })
      );
      if (res && res.msg == 1) {
        return true;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return false;
      }
    } catch (err) {

      this.tost.openSnackBar(`Failed to clear ${JSON.stringify(err)}`, 'E');
      return false;
    }
  }



  async clearAllResolvedTicketsAsAdmin(nCaseid): Promise<boolean> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<any>(`${environment.cloudUrl}${environment.coreservice}/ticket/adminclearticket`, { nCaseid: nCaseid })
      );
      if (res && res.msg == 1) {
        return true;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return false;
      }
    } catch (err) {

      this.tost.openSnackBar(`Failed to clear ${JSON.stringify(err)}`, 'E');
      return false;
    }
  }



  async resolveTicket(nTicketid): Promise<boolean> {
    try {

      const res: any = await firstValueFrom(
        this.http.post<any>(`${environment.cloudUrl}${environment.coreservice}/ticket/resolved`, { nTicketid: nTicketid })
      );
      if (res && res.msg == 1) {
        return true;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return false;
      }
    } catch (err) {

      this.tost.openSnackBar(`Failed to clear ${JSON.stringify(err)}`, 'E');
      return false;
    }
  }

  async getCaseList(): Promise<caselistRes[]> {
    let res: any = [];
    try {
      res = await firstValueFrom(
        this.http.get<caselistRes[]>(
          `${environment.cloudUrl}${environment.coreservice}/ticket/caselist`,
        )
      );
    } catch (error) {
      console.error(error)
      res = [];
    }
    return res;
  }

  async moduleimageUpload(mdl: FormData): Promise<TicketImageUpload> {
    try {
      const res = await firstValueFrom(
        this.http.post<any>(
          `${environment.uploadservice}/helpcenter/upload-image-ticket`, mdl)
      );
      if (res.msg == -1) {
        this.tost.openSnackBar(`Image Upload failed ${res.error}`, 'E');
        return { msg: -1, error: res.error, value: '' };
      }
      else {
        return res;
      }
    } catch (err: any) {
      this.tost.openSnackBar(`Image Upload failed ${err}`, 'E');
      return { msg: -1, error: err, value: '' };
    }
  }



  async submitTicket(nCaseid: string, cSession: string, cDesc: string, cImage: string, cImagename: string): Promise<boolean> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<any>(`${environment.cloudUrl}${environment.coreservice}/ticket/ticketbuilder`, { nCaseid: nCaseid, cSession: cSession, cDesc: cDesc, cImage: cImage, cImagename: cImagename })
      );
      if (res && res.msg == 1) {
        return true;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return false;
      }
    } catch (err) {

      this.tost.openSnackBar(`Ticket Not Submitted ${JSON.stringify(err)}`, 'E');
      return false;
    }
  }

}
